'use strict';
(()=>{
  const perfumeUrl='/shop/?collection=perfume#collection';
  const finalImages={'Black London':'/assets/spray-products-final/black-london-new.png','Sweet Rose':'/assets/spray-products-final/sweet-rose-new.png','Velvet Night':'/assets/spray-products-final/velvet-night-new.png','Machmoun':'/assets/spray-products-final/machmoun-new.png','Cotton Candy':'/assets/spray-products-final/cotton-candy-new.png','بلاك لندن':'/assets/spray-products-final/black-london-new.png','سويت روز':'/assets/spray-products-final/sweet-rose-new.png','فيلفت نايت':'/assets/spray-products-final/velvet-night-new.png','المشموم':'/assets/spray-products-final/machmoun-new.png','كوتن كاندي':'/assets/spray-products-final/cotton-candy-new.png'};
  const style=document.createElement('style');style.textContent=`
  @media(min-width:701px){#home-products,#bakhoor-products{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:38px 25px!important;max-width:none!important;margin-left:0!important;margin-right:0!important}#home-products .product-card,#bakhoor-products .product-card{min-width:0!important;width:auto!important}body.home-visual-nav header nav{display:none!important}body.home-visual-nav header{grid-template-columns:1fr auto 1fr}}
  .visual-home-menu{background:#fff;border-bottom:1px solid var(--line);padding:28px 4.5% 32px}.visual-home-menu-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}.visual-home-menu-head .eyebrow{margin:0}.visual-home-menu-head span{font-size:10px;letter-spacing:1.2px;color:var(--muted);text-transform:uppercase}.visual-home-menu-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.visual-menu-card{position:relative;display:block;aspect-ratio:1.18/1;overflow:hidden;background:#e9dfd0}.visual-menu-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .65s var(--ease),filter .35s ease}.visual-menu-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(15,11,8,.78),rgba(15,11,8,.03) 62%)}.visual-menu-card strong{position:absolute;z-index:2;left:14px;right:14px;bottom:12px;color:#fff;font:400 18px/1.05 var(--serif);text-shadow:0 1px 8px #0008}.visual-menu-card:hover img{transform:scale(1.045);filter:brightness(1.04)}
  @media(max-width:700px){#bakhoor-products{display:flex!important;gap:14px!important;overflow-x:auto!important;overflow-y:hidden!important;scroll-snap-type:x mandatory!important;-webkit-overflow-scrolling:touch!important;padding-bottom:10px!important;margin-right:-5vw!important;margin-left:-5vw!important;padding-right:5vw!important;padding-left:5vw!important;scrollbar-width:none!important}#bakhoor-products::-webkit-scrollbar{display:none!important}#bakhoor-products .product-card{flex:0 0 clamp(245px,72vw,330px)!important;scroll-snap-align:start!important;min-width:0!important}.visual-home-menu{padding:22px 0 24px}.visual-home-menu-head{padding:0 18px;margin-bottom:14px}.visual-home-menu-head span{display:none}.visual-home-menu-grid{display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;padding:0 18px 7px;scrollbar-width:none}.visual-home-menu-grid::-webkit-scrollbar{display:none}.visual-menu-card{flex:0 0 138px;aspect-ratio:.9/1;scroll-snap-align:start}.visual-menu-card strong{font-size:17px;left:11px;right:8px;bottom:10px}}
  `;document.head.appendChild(style);
  const menuItems=[
    ['Home','/','/assets/campaigns/hero-lafiesta-unified.webp'],
    ['Perfumes','/shop/?collection=perfume#collection','/assets/collection-notes/women-hd.webp'],
    ['Luxury Spray','/room-sprays/','/assets/campaigns/hero-spray-unified.webp'],
    ['Oud & Bakhoor','/oud-bakhoor/','/assets/campaigns/hero-bakhoor-unified.webp'],
    ['Contact','/contact/','/assets/campaigns/sultana-mists.webp'],
    ['Discovery Set','/products/discovery-set/','/assets/campaigns/discovery-set.webp'],
    ['Gifts & Packaging','/shop/?collection=gift#collection','/assets/campaigns/spray-gift.webp'],
    ['Weddings','/wedding-events/','/assets/campaigns/hero-lafiesta-unified.webp'],
    ['Hospitality','/hospitality/','/assets/campaigns/oud-bakhoor.webp'],
    ['B2B & Corporate','/business-corporate/','/assets/campaigns/oud-department-hd.webp'],
    ['Gift Voucher','/shop/?collection=gift-voucher#collection','/assets/campaigns/supplied-gift.jpg'],
    ['Our Story','/our-story/','/assets/campaigns/hero-story-unified.webp']
  ];
  const buildVisualMenu=()=>{if(document.querySelector('.visual-home-menu'))return;document.body.classList.add('home-visual-nav');const hero=document.querySelector('.hero-carousel');if(!hero)return;const section=document.createElement('section');section.className='visual-home-menu';section.setAttribute('aria-label','Explore Sultana');section.innerHTML=`<div class="visual-home-menu-head"><p class="eyebrow">EXPLORE SULTANA</p><span>Discover our world</span></div><div class="visual-home-menu-grid">${menuItems.map(([title,href,img])=>`<a class="visual-menu-card" href="${href}"><img src="${img}" alt="" loading="lazy"><strong>${title}</strong></a>`).join('')}</div>`;hero.insertAdjacentElement('afterend',section)};
  const syncPrivateCollection=()=>{const g=document.querySelector('#bakhoor-products');if(!g||typeof products==='undefined'||typeof card!=='function')return;g.innerHTML=['sultana-oud','royal-bukhoor','amber-night','oud-collection-set'].map(id=>products.find(p=>p.id===id)).filter(Boolean).map(card).join('')};
  const syncHomeSprays=()=>{const g=document.querySelector('#home-products');if(!g)return;[...g.querySelectorAll('.product-card')].slice(4).forEach(e=>e.remove());g.querySelectorAll('.product-card').forEach(c=>{const t=(c.querySelector('h3')?.textContent||'').trim(),src=finalImages[t],img=c.querySelector('img');if(src&&img){img.src=src;img.removeAttribute('srcset')}})};
  const syncStoryHero=()=>{const img=document.querySelector('#hero-our-story img');if(!img)return;const mobile=window.matchMedia('(max-width:700px)').matches;img.src=mobile?'/assets/campaigns/hero-story-mobile.webp':'/assets/campaigns/hero-story-unified.webp';img.removeAttribute('srcset');};
  const apply=()=>{buildVisualMenu();syncHomeSprays();syncPrivateCollection();syncStoryHero();const l=document.querySelector('#best-sellers .text-link');if(l){l.href=perfumeUrl;l.innerHTML='Explore more <span aria-hidden="true">↗</span>'}};
  const mq=window.matchMedia('(max-width:700px)');if(mq.addEventListener)mq.addEventListener('change',syncStoryHero);else mq.addListener(syncStoryHero);
  document.addEventListener('click',e=>{const l=e.target.closest('#best-sellers .text-link');if(!l)return;e.preventDefault();e.stopImmediatePropagation();location.href=perfumeUrl},true);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});else apply();
})();
